<?php require __DIR__.'/includes/functions.php'; if(user()) redirect('/'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf(); $s=db()->prepare('SELECT * FROM users WHERE mobile=? LIMIT 1'); $s->execute([trim($_POST['mobile']??'')]); $u=$s->fetch(); if($u && password_verify($_POST['password']??'', $u['password_hash'])){session_regenerate_id(true); $_SESSION['user']=['id'=>$u['id'],'role'=>$u['role'],'name'=>$u['name']]; audit('login','user',(int)$u['id']); redirect(in_array($u['role'],['admin','counselor'],true)?'/admin/index.php':'/student/index.php');} $error='شماره موبایل یا رمز عبور صحیح نیست.';} layout_start('ورود'); ?><div class="auth card"><h1>ورود</h1><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>شماره موبایل<input name="mobile" inputmode="tel" required autocomplete="username"></label><label>رمز عبور<input type="password" name="password" required autocomplete="current-password"></label><button class="button" type="submit">ورود</button></form><p class="muted">اطلاعات ورود را از مدیر سامانه دریافت کنید.</p></div><?php layout_end(); ?>
